CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,category_id INTEGER,name TEXT NOT NULL,description TEXT,ingredients TEXT,price REAL NOT NULL,old_price REAL,image TEXT,available INTEGER DEFAULT 1,visible INTEGER DEFAULT 1,featured INTEGER DEFAULT 0,badge TEXT,sort INTEGER DEFAULT 0,addons TEXT DEFAULT '[]');
CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,image TEXT,price REAL,old_price REAL,ends_at TEXT,active INTEGER DEFAULT 1,product_ids TEXT DEFAULT '[]');
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,name TEXT,phone TEXT,address TEXT,notes TEXT,items TEXT,subtotal REAL,delivery REAL,total REAL,status TEXT DEFAULT 'new',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
